"""Task-object contact friction — the single source of truth.

The table stores the PHYSICAL pair friction (a real silicone fingertip pad against
a material class). That is a fact about the world, independent of which hand is
mounted, because all three hands carry silicone-class fingertips and share the
same engine-side pad value. The number PhysX actually needs is derived from it:

    mu_obj = 2 * mu_real - PAD_ENGINE_MU

That formula follows from the contact combine rule, which was MEASURED on this
PhysX build with a pull-to-slip experiment and is `average`, not min/max/multiply
(see docs/friction_calibration.md).

Two consequences worth knowing:

- Lower bound. Effective friction can never drop below PAD_ENGINE_MU / 2 = 0.6,
  so genuinely slippery contacts (wet or oiled surfaces, mu ~ 0.2-0.4) are not
  representable. Every task in the family is dry manipulation, so this does not
  bind today.
- Compliant pads bypass the rule entirely. If a fingertip is ever switched to a
  compliant contact (negative restitution), PhysX lets the compliant side win and
  ignores the combine mode — at which point this formula stops holding and the
  values need re-deriving.

Sources for the pair friction (level 0 = published/handbook values; level 1 is an
inclined-plane measurement with a real pad sample, which will replace these
entry by entry):

- hard plastic: silicone against a smooth surface, CoF ~ 1.0 (Jehbco, silicone
  manufacturer technical note)
- metal: silicone against smooth metal, static 0.5-1.0 / kinetic 0.4-0.8 (Eson,
  silicone material supplier)
- wood: soft rubber on dry wood 0.95, hard rubber 0.7 (EngineeringToolbox /
  TeachEngineering friction tables)
- cardboard: rubber on cardboard 0.2-0.6 (engineering friction tables)
- produce: silicone pad against apple skin measured at 0.8; harvesting-gripper
  design reference 0.5 (MDPI Actuators / Agriculture)
- rubber: extrapolated from handbook rubber-on-rubber ranges (no direct
  measurement)
- leather / felt (YCB balls): estimated, not yet measured
"""

import sapien.physx as physx

# Engine-side fingertip pad friction, unified across sharpa / wuji / xhand
# (shadow is on hold pending the XHand decision). Because every hand shares this
# value, the table below is hand-independent. If a level-1 measurement moves this
# number, every derived object friction follows automatically — which is the
# whole reason physical values and engine compensation are kept apart.
PAD_ENGINE_MU = 1.2

# Real contact-pair friction: silicone fingertip pad against the material class,
# dry. These are physical facts, not engine parameters.
REAL_PAIR_MU = {
    "hard_plastic": 1.0,   # PET/PP/ABS: bottles, caps, keycaps, mouse, laptop shell, gears
    "metal": 0.8,          # steel: bolts, nuts, keys, spoons, knives, sockets, slide rails
    "wood": 0.9,           # drawers, panels, wooden blocks
    "cardboard": 0.55,     # cartons, YCB boxed items
    "produce": 0.6,        # waxy fruit/vegetable skin (cucumber and friends)
    "rubber": 1.5,         # rubber and soft grips (screwdriver handle)
    "leather_felt": 0.6,   # YCB baseball (leather) / tennis ball (felt), estimated
    # --- added for the six remaining long-horizon families ---
    "ceramic": 1.0,        # glazed plate: smooth and hard, same basis as hard plastic
    "bread": 0.6,          # crumbly crust, estimated at the produce level (no measurement)
    "cooked_food": 0.7,    # moist meatball surface, tackier than waxy skin, estimated
    "sugar_crystal": 0.8,  # crystalline faces interlock with a soft pad, estimated
    # --- added for the pipette family ---
    "glass": 1.0,          # borosilicate labware: smooth and hard, same basis as ceramic
}

# Engine-side tabletop / ground friction. Owned by the environment-structure
# layer (tasks/config/contact_materials.py TABLE_FRICTION); mirrored here so the
# object-vs-table pair can be solved without a circular import.
TABLE_ENGINE_MU = 0.30

# Real contact-pair friction: the material class against a dry laminate/wood
# tabletop. Physical facts, same status as REAL_PAIR_MU. Level 0 = handbook
# ranges (EngineeringToolbox / TeachEngineering dry-friction tables); the mid
# point of the published range is taken.
#
#   plastic on wood 0.3-0.5 | steel on wood 0.3-0.5 | wood on wood 0.25-0.5
#   paper-cardboard on wood 0.4-0.6 | rubber on wood 0.7-1.0
REAL_TABLE_MU = {
    "hard_plastic": 0.45,
    "metal": 0.40,
    "wood": 0.40,
    "cardboard": 0.50,
    "produce": 0.50,
    "rubber": 0.90,
    "leather_felt": 0.55,
    "ceramic": 0.40,
    "bread": 0.45,        # estimated
    "cooked_food": 0.45,  # estimated
    "sugar_crystal": 0.55,
    "glass": 0.35,        # glass on a dry laminate/wood top, handbook 0.2-0.5
}

# Which contact pair a given object is solved for. PhysX carries ONE scalar per
# surface and combines with `average`, so N object materials give N degrees of
# freedom against N*(N-1)/2 + N pairs: the system is overdetermined and only a
# chosen subset can be exact. Historically every object was solved for its pad
# pair, which left every object-vs-table and object-vs-object pair as an
# uncontrolled by-product (for produce/cardboard the pad solution clamps to 0,
# collapsing the tabletop pair to 0.15 and object-object to 0.00).
#
# The dominant pair is therefore an explicit, per-object task-layer decision:
#   "pad"      the object is picked up and carried; grip fidelity decides the task
#   "table"    the object mainly rests, slides or is pushed on the tabletop
#   "balanced" both pairs matter; least-squares split of the error
DOMINANT_PAIRS = ("pad", "table", "balanced")


def object_friction(material_class: str, dominant: str = "pad") -> float:
    """Engine friction for an object, solved against the chosen dominant pair.

    ``dominant="pad"`` reproduces the original behaviour exactly and stays the
    default, so every existing call site is bit-for-bit unchanged.

    Clamped at 0: a pair whose real friction sits below half the partner surface
    value cannot be represented exactly, and 0 is as close as the engine gets.
    """
    if dominant not in DOMINANT_PAIRS:
        raise ValueError(
            f"dominant must be one of {DOMINANT_PAIRS}, got {dominant!r}"
        )
    if dominant == "pad":
        return max(0.0, 2.0 * REAL_PAIR_MU[material_class] - PAD_ENGINE_MU)
    if dominant == "table":
        return max(0.0, 2.0 * REAL_TABLE_MU[material_class] - TABLE_ENGINE_MU)
    # balanced: minimise the squared error of both pairs at once.
    #   f(x) = ((PAD+x)/2 - r_pad)^2 + ((TAB+x)/2 - r_tab)^2
    #   f'(x) = 0  =>  x = r_pad + r_tab - (PAD + TAB)/2
    mu = (
        REAL_PAIR_MU[material_class]
        + REAL_TABLE_MU[material_class]
        - 0.5 * (PAD_ENGINE_MU + TABLE_ENGINE_MU)
    )
    return max(0.0, mu)


def effective_pairs(material_class: str, dominant: str = "pad") -> dict:
    """Report what the chosen solution actually does to both contact pairs.

    Returned so audits and ledgers can quote the realised pair values instead of
    quoting the engine scalar, which on its own means nothing.
    """
    mu = object_friction(material_class, dominant)
    pad = 0.5 * (PAD_ENGINE_MU + mu)
    table = 0.5 * (TABLE_ENGINE_MU + mu)
    return {
        "mu_object": mu,
        "dominant": dominant,
        "pad_pair": pad,
        "pad_real": REAL_PAIR_MU[material_class],
        "pad_error": pad - REAL_PAIR_MU[material_class],
        "table_pair": table,
        "table_real": REAL_TABLE_MU[material_class],
        "table_error": table - REAL_TABLE_MU[material_class],
    }


def object_material(
    material_class: str, restitution: float = 0.0, dominant: str = "pad"
) -> physx.PhysxMaterial:
    """Build the PhysxMaterial for a material class (static = dynamic = object_friction)."""
    mu = object_friction(material_class, dominant)
    return physx.PhysxMaterial(mu, mu, restitution)
